<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import AssistantChat from './AssistantChat.vue'
import {aiWorkspace} from '../services/aiWorkspace'
import {registerOrbMotion} from '../services/orbMotion'
import {useAuthStore} from '../stores/auth'
const route=useRoute(),hiddenOnExplore=computed(()=>route.path==='/ai'||route.path.startsWith('/ai/'))
const chat=ref<InstanceType<typeof AssistantChat>>(),orbButton=ref<HTMLElement>(),full=ref(false),interacting=ref(false)
const assistantBusy=computed(()=>Boolean(chat.value?.busy))
let stopOrbMotion:(()=>void)|undefined
function toggle(){if(hiddenOnExplore.value)return;if(open.value){close();return}full.value=aiWorkspace.startFull;open.value=true}
function close(){open.value=false;chat.value?.clearSensitive()}
function defaultRect(){const w=Math.min(1120,innerWidth-64),h=Math.min(780,innerHeight-72);return {x:Math.round((innerWidth-w)/2),y:Math.round((innerHeight-h)/2),w,h}}
const auth=useAuthStore(),open=ref(false),rect=ref(defaultRect())
const storageKey='mi2_float_geometry_source_v2_'+auth.user?.id
const style=computed(()=>full.value?{left:'0px',top:'0px',width:'100vw',height:'100dvh'}:({left:rect.value.x+'px',top:rect.value.y+'px',width:rect.value.w+'px',height:rect.value.h+'px'}))
function clamp(){const r=rect.value;r.w=Math.max(Math.min(680,innerWidth-24),Math.min(r.w,innerWidth-16));r.h=Math.max(Math.min(360,innerHeight-16),Math.min(r.h,innerHeight-16));r.x=Math.max(8,Math.min(r.x,innerWidth-r.w-8));r.y=Math.max(8,Math.min(r.y,innerHeight-r.h-8))}
function save(){clamp();localStorage.setItem(storageKey,JSON.stringify(rect.value))}
let action:{x:number,y:number,rect:typeof rect.value,resize:string}|null=null
function start(e:PointerEvent,resize=''){if(e.button!==0||full.value)return;interacting.value=true;action={x:e.clientX,y:e.clientY,rect:{...rect.value},resize};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);e.preventDefault()}
function move(e:PointerEvent){if(!action)return;const dx=e.clientX-action.x,dy=e.clientY-action.y,r=action.rect,edge=action.resize;rect.value={...r};if(!edge){rect.value.x=r.x+dx;rect.value.y=r.y+dy}else{if(edge.includes('e'))rect.value.w=r.w+dx;if(edge.includes('s'))rect.value.h=r.h+dy;if(edge.includes('w')){rect.value.w=r.w-dx;rect.value.x=r.x+dx}if(edge.includes('n')){rect.value.h=r.h-dy;rect.value.y=r.y+dy}}clamp()}
function end(){if(action){action=null;interacting.value=false;save()}}
function keyMove(e:KeyboardEvent,resize=false){const d:Record<string,[number,number]>={ArrowLeft:[-16,0],ArrowRight:[16,0],ArrowUp:[0,-16],ArrowDown:[0,16]};if(!d[e.key])return;e.preventDefault();const [x,y]=d[e.key]!;if(resize){rect.value.w+=x;rect.value.h+=y}else{rect.value.x+=x;rect.value.y+=y}save()}
function openAssistant(){if(hiddenOnExplore.value)return;open.value=true;full.value=aiWorkspace.startFull}
watch(hiddenOnExplore,hide=>{if(hide&&open.value)close()},{immediate:true})
onMounted(()=>{try{const r=JSON.parse(localStorage.getItem(storageKey)||'null');if(r&&['x','y','w','h'].every(k=>Number.isFinite(r[k])))rect.value=r}catch{}clamp();window.addEventListener('resize',save);window.addEventListener('mi2-open-assistant',openAssistant);stopOrbMotion=registerOrbMotion(()=>orbButton.value,{range:2.8,blink:true,busy:assistantBusy})})
onBeforeUnmount(()=>{stopOrbMotion?.();window.removeEventListener('resize',save);window.removeEventListener('mi2-open-assistant',openAssistant)})
</script>
<template><button v-if="!hiddenOnExplore" ref="orbButton" class="assistant-orb" :class="{'is-open':open,'is-busy':assistantBusy,'pref-reduced-motion':aiWorkspace.reduced}" :aria-expanded="open" aria-controls="floating-assistant-window" aria-label="打开悬浮 AI 助手" @click="toggle"><span class="orb-visual"><img src="/m9/assistant-orb.png" alt=""/><span class="eye left"></span><span class="eye right"></span></span></button><Transition name="mi-float-win"><section v-show="open&&!hiddenOnExplore" id="floating-assistant-window" class="floating-window" :class="{'is-full':full,'is-interacting':interacting,'pref-reduced-motion':aiWorkspace.reduced}" :style="style" role="dialog" aria-label="悬浮 AI 助手"><button v-if="!full" class="prototype-drag" aria-label="移动助手窗口（方向键）" @pointerdown="start($event)" @pointermove="move" @pointerup="end" @pointercancel="end" @keydown="keyMove($event)"><span></span></button><div class="floating-chat"><AssistantChat ref="chat" surface="floating" @close="close" @toggle-full="full=!full"/></div><button v-for="edge in full?[]:['n','s','w','e','nw','ne','sw','se']" :key="edge" class="resize-handle" :class="'edge-'+edge" :aria-label="'调整窗口 '+edge+' 边缘（方向键）'" @pointerdown="start($event,edge)" @pointermove="move" @pointerup="end" @pointercancel="end" @keydown="keyMove($event,true)"></button></section></Transition></template>
<style scoped>
.assistant-orb{position:fixed;z-index:110;bottom:24px;right:26px;width:69px;height:69px;background:transparent;border:0;border-radius:50%;cursor:pointer;padding:0;isolation:isolate;--ex:0px;--ey:0px;--blink:1}.orb-visual{position:relative;display:block;width:100%;height:100%;border-radius:50%;pointer-events:none;transition:scale .24s cubic-bezier(.22,1,.36,1);animation:assistantOrbFloat 5.2s ease-in-out infinite}.orb-visual::before{content:"";position:absolute;inset:-20%;z-index:0;border-radius:50%;pointer-events:none;background:radial-gradient(circle,rgba(154,102,255,.52) 0%,rgba(124,72,235,.22) 42%,transparent 70%);opacity:.72;transform:scale(.95);transition:opacity .25s ease,transform .25s ease;animation:assistantOrbHalo 4.8s ease-in-out infinite}.orb-visual img{position:relative;z-index:2;width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;user-select:none}.assistant-orb:hover .orb-visual{scale:1.06}.assistant-orb:hover .orb-visual::before{opacity:1;transform:scale(1.06)}.assistant-orb:active .orb-visual{scale:.94;transition-duration:.1s}.assistant-orb.is-open .orb-visual{animation-play-state:paused}.assistant-orb.is-open .orb-visual::before{opacity:.95;transform:scale(1.04)}.assistant-orb.is-busy .orb-visual::before{background:radial-gradient(circle,rgba(182,138,255,.78) 0%,rgba(138,90,248,.34) 45%,transparent 72%);animation:assistantOrbThink 1.35s ease-in-out infinite}.eye{position:absolute;z-index:3;top:43.2%;width:7.6%;height:22%;background:white;border-radius:9px;box-shadow:0 0 8px rgba(255,255,255,.72),0 0 14px rgba(184,170,255,.45);pointer-events:none;transform-origin:center;transform:translate3d(var(--ex),var(--ey),0) scaleY(var(--blink));transition:transform .11s cubic-bezier(.22,1,.36,1)}.eye.left{left:32.2%}.eye.right{left:60.8%}.floating-window{position:fixed;z-index:120;display:flex;flex-direction:column;border-radius:18px;background:var(--mi-bg);box-shadow:var(--mi-shadow-lg);color:var(--mi-text);overflow:hidden;border:1px solid var(--mi-border-strong);transform-origin:bottom right;transition:left .24s cubic-bezier(.22,1,.36,1),top .24s cubic-bezier(.22,1,.36,1),width .24s cubic-bezier(.22,1,.36,1),height .24s cubic-bezier(.22,1,.36,1),border-radius .24s ease}.floating-window.is-interacting{transition:none!important;user-select:none}.floating-window.is-full{transform-origin:center center}.mi-float-win-enter-active{transition:opacity .24s cubic-bezier(.22,1,.36,1),transform .24s cubic-bezier(.22,1,.36,1)!important}.mi-float-win-leave-active{transition:opacity .18s cubic-bezier(.4,0,1,1),transform .18s cubic-bezier(.4,0,1,1)!important}.mi-float-win-enter-from,.mi-float-win-leave-to{opacity:0;transform:translate3d(0,14px,0) scale(.92)}.floating-window.is-full.mi-float-win-enter-from,.floating-window.is-full.mi-float-win-leave-to{opacity:0;transform:scale(.97)}.floating-chat{flex:1;min-height:0;overflow:hidden}.resize-handle{position:absolute;right:0;bottom:0;width:24px;height:24px;cursor:nwse-resize;background:transparent;border:0;touch-action:none}.resize-handle:after{content:'';position:absolute;right:6px;bottom:6px;width:9px;height:9px;border-right:2px solid var(--mi-border-strong);border-bottom:2px solid var(--mi-border-strong)}.floating-window :focus-visible,.assistant-orb:focus-visible{outline:2px solid var(--mi-accent);outline-offset:-3px}

.prototype-drag{position:absolute;z-index:50;top:0;left:30%;width:40%;height:12px;background:transparent;border:0;cursor:move;touch-action:none}.prototype-drag span{display:block;margin:2px auto;width:36px;height:3px;border-radius:4px;background:var(--mi-border-strong)}.floating-window.is-full{border-radius:0;border:0}.floating-chat{height:100%}.resize-handle:after{display:none}.edge-n,.edge-s{left:12px;right:12px;width:auto;height:6px;cursor:ns-resize}.edge-n{top:0;bottom:auto}.edge-s{bottom:0}.edge-w,.edge-e{top:12px;bottom:12px;width:6px;height:auto;cursor:ew-resize}.edge-w{left:0;right:auto}.edge-e{right:0}.edge-nw,.edge-ne,.edge-sw,.edge-se{width:14px;height:14px}.edge-nw{top:0;left:0;right:auto;bottom:auto}.edge-ne{top:0;right:0;bottom:auto;cursor:nesw-resize}.edge-sw{bottom:0;left:0;right:auto;cursor:nesw-resize}.edge-se{bottom:0;right:0}
@keyframes assistantOrbFloat{0%,100%{transform:translate3d(0,0,0)}50%{transform:translate3d(0,-3.5px,0)}}
@keyframes assistantOrbHalo{0%,100%{opacity:.6;transform:scale(.94)}50%{opacity:.92;transform:scale(1.05)}}
@keyframes assistantOrbThink{0%,100%{opacity:.55;transform:scale(.92)}50%{opacity:1;transform:scale(1.14)}}
.assistant-orb.pref-reduced-motion .orb-visual,.assistant-orb.pref-reduced-motion .orb-visual::before,.assistant-orb.pref-reduced-motion .eye,.floating-window.pref-reduced-motion{animation:none!important;transition:none!important}
@media(prefers-reduced-motion:reduce){.orb-visual,.orb-visual::before,.assistant-orb .eye,.floating-window,.mi-float-win-enter-active,.mi-float-win-leave-active{animation:none!important;transition:none!important}}
/* 悬浮助手：文字跟随主题正文色 */
:deep(.thread),:deep(.chat-main),:deep(.reply-body),:deep(.bubble),:deep(.assistant-name),:deep(.movie-title),:deep(.movie-meta),:deep(.why),:deep(.date-line),:deep(.trust-note),:deep(.cards-head){color:var(--mi-text)!important}
:deep(.reply-body strong),:deep(.reply-body b){color:var(--mi-text)!important}</style>